/* =========================================================
 * ncsg-content-merged.css
 *
 * For Hexo Fluid:
 * 1. Markdown table horizontal scroll
 * 2. Markdown table light/dark mode adaptation
 * 3. Code block horizontal scroll + line number gutter
 * 4. Prevent table styles from polluting Hexo highlight code tables
 * ========================================================= */


/* =========================================================
 * 0. Theme variables
 * ========================================================= */

:root {
    /* ---------- Markdown table: light mode ---------- */
    --ncsg-table-text: #2f3542;
    --ncsg-table-bg: #ffffff;
    --ncsg-table-head-bg: #f3f6fa;
    --ncsg-table-stripe-bg: #fafbfc;
    --ncsg-table-hover-bg: #f1f5f9;
    --ncsg-table-border: rgba(80, 100, 120, 0.32);
    --ncsg-table-scrollbar: rgba(100, 116, 139, 0.38);
    --ncsg-table-scrollbar-hover: rgba(100, 116, 139, 0.6);

    /* ---------- Code block: light mode ---------- */
    --ncsg-code-bg: #ffffff;
    --ncsg-code-gutter-bg: #f1f3f5;
    --ncsg-code-gutter-text: #7a828c;
    --ncsg-code-gutter-border: rgba(80, 95, 115, 0.18);
}


/* =========================================================
 * 0.1 Dark mode variables
 *
 * Compatible with Fluid and common dark-mode selectors.
 * ========================================================= */

html[data-user-color-scheme="dark"],
body[data-user-color-scheme="dark"],
[data-user-color-scheme="dark"],
html.dark,
body.dark,
html[data-theme="dark"],
body[data-theme="dark"] {
    /* ---------- Markdown table: dark mode ---------- */
    --ncsg-table-text: #c9d1d9;
    --ncsg-table-bg: #222832;
    --ncsg-table-head-bg: #2d3542;
    --ncsg-table-stripe-bg: #262e39;
    --ncsg-table-hover-bg: #323c4a;
    --ncsg-table-border: rgba(148, 163, 184, 0.35);
    --ncsg-table-scrollbar: rgba(148, 163, 184, 0.42);
    --ncsg-table-scrollbar-hover: rgba(148, 163, 184, 0.68);

    /* ---------- Code block: dark mode ---------- */
    --ncsg-code-bg: #282c34;
    --ncsg-code-gutter-bg: #242932;
    --ncsg-code-gutter-text: #9aa4b2;
    --ncsg-code-gutter-border: rgba(255, 255, 255, 0.12);
}


/* ---------- Fallback: system dark mode ---------- */
@media (prefers-color-scheme: dark) {
    :root:not([data-user-color-scheme="light"]) {
        --ncsg-table-text: #c9d1d9;
        --ncsg-table-bg: #222832;
        --ncsg-table-head-bg: #2d3542;
        --ncsg-table-stripe-bg: #262e39;
        --ncsg-table-hover-bg: #323c4a;
        --ncsg-table-border: rgba(148, 163, 184, 0.35);
        --ncsg-table-scrollbar: rgba(148, 163, 184, 0.42);
        --ncsg-table-scrollbar-hover: rgba(148, 163, 184, 0.68);

        --ncsg-code-bg: #282c34;
        --ncsg-code-gutter-bg: #242932;
        --ncsg-code-gutter-text: #9aa4b2;
        --ncsg-code-gutter-border: rgba(255, 255, 255, 0.12);
    }
}


/* =========================================================
 * 1. Markdown table horizontal scroll
 *
 * Important:
 * Exclude Hexo highlight tables:
 *   figure.highlight table
 *
 * The previous bug was caused by broad selectors like:
 *   #board table
 * They also matched code-block internal tables.
 * ========================================================= */

:where(.markdown-body, .post-content, .article-content, #board)
table:not(.highlight):not(figure.highlight table):not(.highlight table) {
    display: block !important;

    width: max-content !important;
    max-width: 100% !important;

    overflow-x: auto !important;
    overflow-y: hidden !important;

    margin: 1rem 0 !important;

    border-collapse: collapse !important;
    border-spacing: 0 !important;

    color: var(--ncsg-table-text) !important;
    background-color: var(--ncsg-table-bg) !important;

    -webkit-overflow-scrolling: touch;
}


/* =========================================================
 * 2. Markdown table cell style
 * ========================================================= */

:where(.markdown-body, .post-content, .article-content, #board)
table:not(.highlight):not(figure.highlight table):not(.highlight table)
:is(th, td) {
    padding: 0.45rem 0.75rem !important;

    border: 1px solid var(--ncsg-table-border) !important;

    line-height: 1.6 !important;
    vertical-align: middle !important;

    white-space: nowrap !important;

    color: var(--ncsg-table-text) !important;
    background-color: var(--ncsg-table-bg) !important;
}


/* =========================================================
 * 3. Markdown table header style
 * ========================================================= */

:where(.markdown-body, .post-content, .article-content, #board)
table:not(.highlight):not(figure.highlight table):not(.highlight table)
th {
    font-weight: 700 !important;
    text-align: center !important;

    color: var(--ncsg-table-text) !important;
    background-color: var(--ncsg-table-head-bg) !important;
}


/* =========================================================
 * 4. Markdown table body style
 * ========================================================= */

:where(.markdown-body, .post-content, .article-content, #board)
table:not(.highlight):not(figure.highlight table):not(.highlight table)
td {
    color: var(--ncsg-table-text) !important;
    background-color: var(--ncsg-table-bg) !important;
}


/* =========================================================
 * 5. Markdown table zebra stripe
 * ========================================================= */

:where(.markdown-body, .post-content, .article-content, #board)
table:not(.highlight):not(figure.highlight table):not(.highlight table)
tbody tr:nth-child(even) td {
    background-color: var(--ncsg-table-stripe-bg) !important;
}


/* =========================================================
 * 6. Markdown table hover effect
 * ========================================================= */

:where(.markdown-body, .post-content, .article-content, #board)
table:not(.highlight):not(figure.highlight table):not(.highlight table)
tbody tr:hover td {
    background-color: var(--ncsg-table-hover-bg) !important;
}


/* =========================================================
 * 7. Markdown table scrollbar style
 * ========================================================= */

:where(.markdown-body, .post-content, .article-content, #board)
table:not(.highlight):not(figure.highlight table):not(.highlight table)::-webkit-scrollbar {
    height: 8px;
}

:where(.markdown-body, .post-content, .article-content, #board)
table:not(.highlight):not(figure.highlight table):not(.highlight table)::-webkit-scrollbar-track {
    background: transparent;
}

:where(.markdown-body, .post-content, .article-content, #board)
table:not(.highlight):not(figure.highlight table):not(.highlight table)::-webkit-scrollbar-thumb {
    background-color: var(--ncsg-table-scrollbar);
    border-radius: 999px;
}

:where(.markdown-body, .post-content, .article-content, #board)
table:not(.highlight):not(figure.highlight table):not(.highlight table)::-webkit-scrollbar-thumb:hover {
    background-color: var(--ncsg-table-scrollbar-hover);
}


/* =========================================================
 * 8. Code block scroll + line number gutter + toolbar
 * ========================================================= */

/*
 * 说明：
 * 1. figure.highlight 本身不再承担滚动。
 * 2. JS 会把代码表格包进 .ncsg-code-scroll。
 * 3. .ncsg-code-scroll 负责横向 / 纵向滚动。
 * 4. 展开后取消 max-height，从而显示完整代码。
 */

figure.highlight {
    --ncsg-code-font-family: "JetBrains Mono",
    "Fira Code",
    "Cascadia Code",
    "SFMono-Regular",
    Consolas,
    "Liberation Mono",
    Menlo,
    Monaco,
    monospace;

    --ncsg-code-font-size: 0.92rem;
    --ncsg-code-line-height: 1.65;
    --ncsg-code-padding-y: 0.85rem;

    /*
     * 折叠状态下代码块最大高度。
     * 可以按喜好改成 420px、520px、60vh 等。
     */
    --ncsg-code-collapsed-max-height: 520px;

    margin: 1rem 0 !important;
    padding: 0 !important;

    background: var(--ncsg-code-bg) !important;
    border-radius: 6px;

    /*
     * 重要：
     * figure 本身不滚动，避免 toolbar 和代码一起滚动导致布局混乱。
     */
    overflow: hidden !important;

    position: relative;
}

/* 工具栏 */
figure.highlight .ncsg-code-toolbar {
  display: flex !important;
  justify-content: space-between !important;
  align-items: center !important;
  gap: 0.75rem !important;

  padding: 0.45rem 0.55rem !important;

  background: var(--ncsg-code-bg) !important;
  border-bottom: 1px solid var(--ncsg-code-gutter-border) !important;

  user-select: none !important;
}

/* 左侧语言标签 */
figure.highlight .ncsg-code-lang {
  display: inline-flex;
  align-items: center;

  min-width: 0;

  padding-left: 0.25rem;

  font-family:
    "JetBrains Mono",
    "Fira Code",
    "Cascadia Code",
    "SFMono-Regular",
    Consolas,
    "Liberation Mono",
    Menlo,
    Monaco,
    monospace;

  font-size: 0.78rem;
  line-height: 1;

  color: var(--ncsg-code-gutter-text);

  opacity: 0.85;
  white-space: nowrap;
}

/* 没识别到语言时隐藏 */
figure.highlight .ncsg-code-lang:empty {
  display: none;
}

/* 右侧按钮容器 */
figure.highlight .ncsg-code-actions {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 0.45rem;

  margin-left: auto;
}

/* 工具栏按钮 */
figure.highlight .ncsg-code-btn {
  appearance: none;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  width: 1.75rem;
  height: 1.75rem;

  padding: 0;

  border: 1px solid var(--ncsg-code-gutter-border);
  border-radius: 4px;

  cursor: pointer;

  color: var(--ncsg-code-gutter-text);
  background: transparent;

  transition:
    background-color 0.15s ease,
    color 0.15s ease,
    border-color 0.15s ease,
    opacity 0.15s ease;
}

figure.highlight .ncsg-code-btn:hover {
  color: inherit;
  background: rgba(127, 127, 127, 0.12);
}

figure.highlight .ncsg-code-btn svg {
  width: 1rem;
  height: 1rem;

  display: block;

  stroke: currentColor;
  fill: none;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;

  pointer-events: none;
}

/* 不需要展开时隐藏展开按钮 */
figure.highlight .ncsg-code-toggle.ncsg-code-toggle-hidden {
  display: none !important;
}

/* 复制成功/失败时的轻微状态提示 */
figure.highlight .ncsg-code-btn.ncsg-code-copied {
  color: #22c55e;
  border-color: rgba(34, 197, 94, 0.55);
}

figure.highlight .ncsg-code-btn.ncsg-code-failed {
  color: #ef4444;
  border-color: rgba(239, 68, 68, 0.55);
}

/*
 * JS 创建的滚动容器。
 * 折叠状态：
 * - 横向滚动：保留
 * - 纵向滚动：超过最大高度才出现
 */
figure.highlight .ncsg-code-scroll {
    max-height: var(--ncsg-code-collapsed-max-height);

    overflow-x: auto !important;
    overflow-y: auto !important;

    background: var(--ncsg-code-bg) !important;

    -webkit-overflow-scrolling: touch;
}

/*
 * 展开状态：
 * - 不限制高度
 * - 不再纵向滚动
 * - 横向滚动仍然保留
 */
figure.highlight.ncsg-code-expanded .ncsg-code-scroll {
    max-height: none !important;

    overflow-x: auto !important;
    overflow-y: visible !important;
}

/*
 * 如果 JS 还没执行，figure.highlight 下面可能直接是 table。
 * 这个 fallback 保证没有 JS 时仍然能横向滚动。
 */
figure.highlight:not(.ncsg-code-enhanced) {
    overflow-x: auto !important;
    overflow-y: auto !important;
    max-height: var(--ncsg-code-collapsed-max-height);
}

/* Reset internal highlight table */
figure.highlight table {
    display: table !important;

    width: max-content !important;
    min-width: 100% !important;
    max-width: none !important;

    margin: 0 !important;
    padding: 0 !important;

    border-collapse: collapse !important;
    border-spacing: 0 !important;
    table-layout: auto !important;

    overflow: visible !important;

    color: inherit !important;
    background: var(--ncsg-code-bg) !important;
}

/* 防止 Markdown 表格样式污染代码块内部表格 */
figure.highlight table,
figure.highlight thead,
figure.highlight tbody,
figure.highlight tr,
figure.highlight th,
figure.highlight td {
    margin: 0 !important;
    border: 0 !important;
    background-color: transparent !important;
}

/*
 * 所有代码块单元格。
 * 注意：td 本身不要放上下 padding。
 * 上下 padding 统一放到 gutter pre 和 code pre 上。
 */
figure.highlight td {
    padding: 0 !important;
    vertical-align: top !important;

    font-family: var(--ncsg-code-font-family) !important;
    font-size: var(--ncsg-code-font-size) !important;
    line-height: var(--ncsg-code-line-height) !important;
}

/* 行号区域 */
figure.highlight td.gutter {
    position: sticky;
    left: 0;
    z-index: 3;

    width: 3.5em;
    min-width: 3.5em;
    max-width: 3.5em;

    user-select: none;
    text-align: right;

    color: var(--ncsg-code-gutter-text) !important;
    background: var(--ncsg-code-gutter-bg) !important;
    border-right: 1px solid var(--ncsg-code-gutter-border) !important;
}

/* 代码区域 */
figure.highlight td.code {
    color: inherit !important;
    background: var(--ncsg-code-bg) !important;
}

/*
 * 最关键的对齐规则：
 * gutter pre 和 code pre 的这些属性必须完全一致：
 * margin
 * padding-top
 * padding-bottom
 * font-family
 * font-size
 * line-height
 */
figure.highlight td.gutter pre,
figure.highlight td.code pre {
    margin: 0 !important;

    padding-top: var(--ncsg-code-padding-y) !important;
    padding-bottom: var(--ncsg-code-padding-y) !important;

    font-family: var(--ncsg-code-font-family) !important;
    font-size: var(--ncsg-code-font-size) !important;
    line-height: var(--ncsg-code-line-height) !important;

    white-space: pre !important;
    overflow: visible !important;

    background: transparent !important;
}

/* 行号区只设置左右 padding */
figure.highlight td.gutter pre {
    padding-left: 0.8rem !important;
    padding-right: 0.75rem !important;

    color: var(--ncsg-code-gutter-text) !important;
    text-align: right !important;
}

/* 代码区只设置左右 padding */
figure.highlight td.code pre {
    padding-left: 0.9rem !important;
    padding-right: 1rem !important;

    color: inherit !important;
